INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (57, 209, 'Adhesive glue (Acrylic water based) for packing tape', '../upload/image/20180826/20180826130321_14781.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;">Adhesive glue (Acrylic water based) for packing tape</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Adhesive/adhesion glue (Acrylic water based) for packing tape Product Features</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> 1. Phenylalanyl aqueous the copolymerization binder; non-toxic, non-polluting and no volatile inflammable gas,security</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Cover powder, brightness, anti-yellowing, for gold and silver powder printing</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> 3 high peel strength, and 24 hours to reach maximum values ??in the retroperitoneal</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Post-processing performance, embossed embossing 60C / 48hr barbecue non-foaming, not unglued</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Coating machine adaptable to replace oil-based plastic used in existing dry-peritoneal</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> 6. Coating weight of 10-14 grams / square meter (wet glue) lamination temperature of 65-85 C</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Technical parameters</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Solid content [m / m%]: 44.0 / 46.0</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> PH value 6.0 - 8.0</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Tg [C]: -5</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Viscosity [mPa.S] :100-500</span><br/> <span style="color:#009900;font-family:Verdana;font-size:16px;"> Usage: for processing pressure acrylic adhesive tape</span></p> <p><br/></p>', '2026-09-06 20:58:45');
