INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (57, 170, 'Double sides adhesive tape jumbo rolls', '../upload/image/20180826/20180826130518_50410.jpg', '<p></p><p>Double sides adhesive tape jumbo rolls</p> <p>Product Name: hot melt double-sided tape<br/> Double sides adhesive tape jumbo rolls consists of:<br/> Release: release paper<br/> A surface adhesive: hot melt adhesive<br/> Substrate: tissue paper<br/> B surface adhesive: hot melt adhesive<br/> Physical properties:<br/> Total thickness: PET basic:30,80,90,100,120UM,150UM,190UM ....<br/> Tissue basic: 60,100,80,160 UM...<br/> initial tack&gt; 8<br/> 180 degree peel force (the stainless steel plate)&gt; 1.1kg/25mm<br/> holding force of&gt; 10hrs<br/> tensile strength&gt; 7N/cm<br/> The above data is based on<br/> BOPP packing tape finished rolls , masking tape and double sides adhesive tape finished rolls ,smaller rolls<br/> GB4852-84, GB-2792-81, GB-7753-84 test method to detect reliable test results<br/> But does not represent the guaranteed value of the product, due to environmental changes, the test results may vary, the numerical deviation 5%, mass production and the use of bigger and then Try qualified.<br/> Characteristics and Uses:<br/> Senior white tissue paper substrate, solvent-based polyacrylate adhesive coated both sides covered, then covered with easy to peel the timber is made of;<br/> Good initial tack and adhesion good, and easy to use cold resistance, good heat resistance; the plastic surface equatorial good; apply to leather, gift wrap and footwear adhesive stickers, stationery, office</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (57, 169, 'Masking Tape Jumbo Rolls', '../upload/image/20180826/20180826130506_27190.jpg', '<p></p><p>Masking Tape Jumbo Rolls</p> <p>1.) Size :<br/> Thickness: 125,135,150 Mic<br/> Width:520mm,980mm,1020mm,1250mm,1280mm,1500mm,and others <br/> Length: 1500-1800m Color: white<br/> 2.) Featurings :<br/> Basic material : crepe paper Color: Beige Adhesive: rubber glue<br/> Total thickness:&gt; 0.145 mm The adhesive :&gt; 10 # <br/> 180 .c peel:&gt; 5.5 N/25 mm Adhesion:&gt; 6 H <br/> Temperature: room temperature, 60C, 80 C,10C .130 C .150 C.160 C .180 C .190 C .200 C .250 C <br/> Tensile strength:&gt; 75 N/25 mm <br/> Elongation:&gt; 9 <br/> 3.) Main usage:<br/> High strength glue, good performance in paste resume, good stability. Applied to metal coating, circuit boards, copper positioning drilling, plastic positioning and spray, computer casings and electronic positioning spray painting and other purposes.<br/> Quantity: 1200rolls/day.</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (57, 167, 'BOPP crystal adhesive tape jumbo rolls', '../upload/image/20180922/20180922163734_31676.jpg', '<p></p><p>BOPP crystal adhesive tape jumbo rolls</p> <p>BOPP crystal adhesive packing tape jumbo-rolls ( Bopp Transparent &amp; Brown Tapes acrylic water base size &amp; solvent &amp; rubber ) is widely used for slitting into medium/smaller rolls and for heavy-duty cartons sealing .1) BOPP super clear adhesive packaging tape with water based acrylic adhesive, high-tensile strength and adhesion <br/> BOPP adhesive tape also called Packing Sealing Adhesive Tapes,packing tape,adhesive tape,BOPP tape jumbo rolls,BOPP tan tape, BOPP brown tape,Polypropylene tape,BOPP clear tape, BOPP printed tape,BOPP brown tape,BOPP smaller rolls, BOPP water based tape, BOPP solvent based tape,BOPP rubber based tape,BOPP acrylic tape,BOPP crystal tape,BOPP jumbo rolls<br/> 2) Colors: Transparent/clear,tan,yellowish,red,dark brown,light tan,white,red,blue,green,black,multicolor and printed logo/letter so on. <br/> 3) Thickness: 35,36,38,39,40,41,42,45,48,50,53,55,58,60,63,65,68mic<br/> 4) Width: 520mm,980mm,1020mm,1270mm,1280mm,1300mm,1600mm,1620mm,1640mm and others <br/> 5) Length: 3000m,4000m,4500m,6000m<br/> 6.) Size:jumbo rolls tape <br/> 6) Qty: 1200rolls/day<br/> Customer own requirement is available for us. Such as : buyer''s own printed OEM logos,private label,particular size and private package styles.</p>', '2026-09-06 20:58:45');
